32	impl<'a> ModuleResolver<'a> {
33	    pub fn new(registry: &'a NamespaceRegistry) -> ParseResult<Self> {
34	        let bindings = registry
35	            .resolve_files()
36	            .map_err(|e| ParseError::GrammarError(e.to_string()))?;
37	        Ok(Self {
38	            registry,
39	            bindings,
40	            loaded_modules: HashMap::new(),
41	            visiting: HashSet::new(),
42	        })
43	    }
44	
45	    pub fn validate_entry(
46	        &mut self,
47	        entry_path: impl AsRef<Path>,
48	        source: &str,
49	    ) -> ParseResult<Ast> {
50	        let path = entry_path
51	            .as_ref()
52	            .canonicalize()
53	            .unwrap_or_else(|_| entry_path.as_ref().to_path_buf());
54	        let ast = parse_source(source)?;
55	        self.visit(&path, &ast)?;
56	        Ok(ast)
57	    }
58	
59	    pub fn validate_dependencies(
60	        &mut self,
61	        entry_path: impl AsRef<Path>,
62	        ast: &Ast,
63	    ) -> ParseResult<()> {
64	        let path = entry_path
65	            .as_ref()
66	            .canonicalize()
67	            .unwrap_or_else(|_| entry_path.as_ref().to_path_buf());
68	        self.visit(&path, ast)
69	    }
70	
71	    fn visit(&mut self, path: &Path, ast: &Ast) -> ParseResult<()> {
72	        let canonical = if path.to_string_lossy().starts_with("__std__") {
73	            path.to_path_buf()
74	        } else {
75	            path.canonicalize().unwrap_or_else(|_| path.to_path_buf())
76	        };
77	
78	        if self.visiting.contains(&canonical) {
79	            // Build the cycle path from currently visiting modules
80	            let cycle: Vec<String> = self
81	                .visiting
82	                .iter()
83	                .map(|p| p.to_string_lossy().to_string())
84	                .chain(std::iter::once(canonical.to_string_lossy().to_string()))
85	                .collect();
86	            return Err(ParseError::circular_dependency(cycle));
87	        }
88	        if self.loaded_modules.contains_key(&canonical) {
89	            return Ok(());
90	        }
91	
92	        self.visiting.insert(canonical.clone());
93	        let namespace = ast.metadata.namespace.clone().unwrap_or_else(|| {
94	            self.registry
95	                .namespace_for(path)
96	                .unwrap_or(self.registry.default_namespace())
97	                .to_string()
98	        });
99	        let exports = collect_exports(ast);
100	
101	        for import in &ast.metadata.imports {
102	            let dep_path = self.resolve_module_path(&import.from_module)?;
103	            let dependency_ast = self.parse_file(&dep_path)?;
104	            self.visit(&dep_path, &dependency_ast)?;
105	            self.validate_import_targets(import, &dep_path)?;
106	        }
107	
108	        self.loaded_modules.insert(
109	            canonical.clone(),
110	            ModuleInfo {
111	                namespace,
112	                exports,
113	                ast: ast.clone(),
114	            },
115	        );
116	        self.visiting.remove(&canonical);
117	        Ok(())
118	    }
119	
120	    fn parse_file(&self, path: &Path) -> ParseResult<Ast> {
121	        let path_str = path.to_string_lossy();
122	        if path_str.starts_with("__std__") {
123	            let namespace = path_str.strip_prefix("__std__").unwrap();
124	            let content = match namespace {
125	                "std" | "std:core" => include_str!("../../std/core.sea"),
126	                "std:http" => include_str!("../../std/http.sea"),
127	                "std:aws" => include_str!("../../std/aws.sea"),
128	                _ => {
129	                    return Err(ParseError::GrammarError(format!(
130	                        "Unknown std module: {}",
131	                        namespace
132	                    )))
133	                }
134	            };
135	            return parse_source(content);
136	        }
137	
138	        let content = fs::read_to_string(path).map_err(|e| {
139	            ParseError::GrammarError(format!("Failed to read module {}: {}", path.display(), e))
140	        })?;
141	        parse_source(&content)
142	    }
143	
144	    fn resolve_module_path(&self, namespace: &str) -> ParseResult<PathBuf> {
145	        if namespace == "std" || namespace.starts_with("std:") {
146	            return Ok(PathBuf::from(format!("__std__{}", namespace)));
147	        }
148	
149	        self.bindings
150	            .iter()
151	            .find(|binding| binding.namespace == namespace)
152	            .map(|binding| binding.path.clone())
153	            .ok_or_else(|| {
154	                // Find similar namespace for suggestion
155	                let suggestion = self.suggest_similar_namespace(namespace);
156	                ParseError::namespace_not_found(namespace, 0, 0, suggestion)
157	            })
158	    }
159	
160	    fn validate_import_targets(&self, import: &ImportDecl, dep_path: &Path) -> ParseResult<()> {
161	        let canonical = if dep_path.to_string_lossy().starts_with("__std__") {
162	            dep_path.to_path_buf()
163	        } else {
164	            dep_path
165	                .canonicalize()
166	                .unwrap_or_else(|_| dep_path.to_path_buf())
167	        };
168	        let module = self.loaded_modules.get(&canonical).ok_or_else(|| {
169	            ParseError::GrammarError(format!(
170	                "Expected module '{}' to be loaded before validating imports",
171	                dep_path.display()
172	            ))
173	        })?;
174	
175	        match &import.specifier {
176	            ImportSpecifier::Wildcard(_) => Ok(()),
177	            ImportSpecifier::Named(items) => {
178	                for item in items {
179	                    if !module.exports.contains(&item.name) {
180	                        return Err(ParseError::symbol_not_exported(
181	                            &item.name,
182	                            &module.namespace,
183	                            0, // TODO: Extract line from import.location if available
184	                            0,
185	                            module.exports.iter().cloned().collect(),
186	                        ));
187	                    }
188	                }
189	                Ok(())
190	            }
191	        }
192	    }
193	
194	    /// Find a similar namespace name for error suggestions using Levenshtein distance
195	    fn suggest_similar_namespace(&self, target: &str) -> Option<String> {
196	        let available: Vec<&str> = self.bindings.iter().map(|b| b.namespace.as_str()).collect();
197	
198	        available
199	            .iter()
200	            .filter_map(|ns| {
201	                let distance = levenshtein_distance(target, ns);
202	                if distance <= 2 {
203	                    Some((*ns, distance))
204	                } else {
205	                    None
206	                }
207	            })
208	            .min_by_key(|(_, d)| *d)
209	            .map(|(ns, _)| ns.to_string())
210	    }
211	}
