225	fn declaration_name(node: &AstNode) -> Option<&str> {
226	    match node {
227	        AstNode::Entity { name, .. }
228	        | AstNode::Resource { name, .. }
229	        | AstNode::Flow {
230	            resource_name: name,
231	            ..
232	        }
233	        | AstNode::Pattern { name, .. }
234	        | AstNode::Role { name, .. }
235	        | AstNode::Relation { name, .. }
236	        | AstNode::Dimension { name }
237	        | AstNode::UnitDeclaration { symbol: name, .. }
238	        | AstNode::Policy { name, .. }
239	        | AstNode::Instance { name, .. }
240	        | AstNode::ConceptChange { name, .. }
241	        | AstNode::Metric { name, .. }
242	        | AstNode::MappingDecl { name, .. }
243	        | AstNode::ProjectionDecl { name, .. }
244	        | AstNode::Cell { name, .. }
245	        | AstNode::SystemDependency { name, .. }
246	        | AstNode::Runtime { name, .. }
247	        | AstNode::Tool { name, .. }
248	        | AstNode::DependencySet { name, .. }
249	        | AstNode::Service { name, .. }
250	        | AstNode::Mount { name, .. }
251	        | AstNode::Endpoint { name, .. }
252	        | AstNode::NetworkFlow { name, .. }
253	        | AstNode::Credential { name, .. } => Some(name),
254	        AstNode::Export(inner) => declaration_name(&inner.node),
255	        AstNode::Record(r) => Some(&r.name),
256	        AstNode::Enum(e) => Some(&e.name),
257	        AstNode::Operation(o) => Some(&o.name),
258	    }
259	}
