340	impl SourceMap {
341	    #[allow(dead_code)]
342	    /// Parse `sources_json` per reference §7: reject non-object input,
343	    /// duplicate raw keys, duplicate normalized logical IDs, non-string
344	    /// values, and invalid logical paths.
345	    pub(crate) fn parse_json(json: &str) -> Result<Self, Vec<ApplicationDiagnostic>> {
346	        let pairs = raw_json_object_pairs(json).map_err(|msg| {
347	            vec![ApplicationDiagnostic::closure_error(
348	                APP014_UNRESOLVED_SPECIFIER,
349	                format!("sources_json is not a valid JSON object of strings: {msg}"),
350	            )]
351	        })?;
352	        let mut raw_seen = HashSet::new();
353	        let mut map = IndexMap::new();
354	        let mut diags = Vec::new();
355	        for (raw_key, value) in pairs {
356	            if !raw_seen.insert(raw_key.clone()) {
357	                diags.push(ApplicationDiagnostic::closure_error(
358	                    APP014_SYMBOL_COLLISION,
359	                    format!("duplicate raw source key '{raw_key}'"),
360	                ));
361	                continue;
362	            }
363	            let normalized = match normalize_logical_path(&raw_key) {
364	                Ok(p) => p,
365	                Err(reason) => {
366	                    diags.push(ApplicationDiagnostic::closure_error(
367	                        APP014_UNRESOLVED_SPECIFIER,
368	                        format!("invalid logical path '{raw_key}': {reason}"),
369	                    ));
370	                    continue;
371	                }
372	            };
373	            if map.insert(normalized.clone(), value).is_some() {
374	                diags.push(ApplicationDiagnostic::closure_error(
375	                    APP014_SYMBOL_COLLISION,
376	                    format!("duplicate normalized logical ID '{normalized}'"),
377	                ));
378	            }
379	        }
380	        if diags.is_empty() {
381	            Ok(Self(map))
382	        } else {
383	            Err(diags)
384	        }
385	    }
386	}
