530	/// Resolve one deterministic semantic closure from an in-memory source map
531	/// (reference §7). All diagnostics are APP014 with a closed reason value,
532	/// except parse failures which are APP015 (the module fails its language
533	/// schema before closure identity exists).
534	// ponytail: consumed by application resolution in Task 7.
535	#[allow(dead_code)]
536	pub(crate) fn resolve_source_map(
537	    entry_logical_path: &str,
538	    sources: &SourceMap,
539	) -> Result<ResolvedModuleSet, Vec<ApplicationDiagnostic>> {
540	    let mut diags: Vec<ApplicationDiagnostic> = Vec::new();
541	
542	    // Parse every module up front; the set is closed and namespace imports
543	    // need every module's declared namespace anyway.
544	    let mut parsed: IndexMap<String, (String, Ast)> = IndexMap::new();
545	    for (logical_id, source) in &sources.0 {
546	        match parse_source(source) {
547	            Ok(ast) => {
548	                parsed.insert(logical_id.clone(), (source.clone(), ast));
549	            }
550	            Err(e) => {
551	                let mut d = ApplicationDiagnostic::new(
552	                    ApplicationDiagnosticCode::App015,
553	                    format!("module '{logical_id}' failed to parse: {e}"),
554	                )
555	                .with_document_kind("authored_source");
556	                d.context.logical_module_id = Some(logical_id.clone());
557	                diags.push(d);
558	            }
559	        }
560	    }
561	    if !diags.is_empty() {
562	        return Err(diags);
563	    }
564	
565	    let entry = normalize_logical_path(entry_logical_path).map_err(|reason| {
566	        vec![ApplicationDiagnostic::closure_error(
567	            APP014_UNRESOLVED_SPECIFIER,
568	            format!("invalid entry logical path '{entry_logical_path}': {reason}"),
569	        )]
570	    })?;
571	    if !parsed.contains_key(&entry) {
572	        return Err(vec![ApplicationDiagnostic::closure_error(
573	            APP014_UNRESOLVED_SPECIFIER,
574	            format!("entry '{entry}' is not present in sources_json"),
575	        )]);
576	    }
577	
578	    // DFS closure walk from the entry.
579	    let mut std_modules: IndexMap<String, (String, Ast)> = IndexMap::new();
580	    let mut reachable: HashSet<String> = HashSet::new();
581	    let mut visiting: Vec<String> = Vec::new();
582	    let mut import_graph: Vec<ImportEdge> = Vec::new();
583	    let mut aliases: Vec<AliasBinding> = Vec::new();
584	
585	    #[allow(clippy::too_many_arguments)]
586	    fn visit(
587	        logical_id: &str,
588	        parsed: &IndexMap<String, (String, Ast)>,
589	        std_modules: &mut IndexMap<String, (String, Ast)>,
590	        reachable: &mut HashSet<String>,
591	        visiting: &mut Vec<String>,
592	        import_graph: &mut Vec<ImportEdge>,
593	        aliases: &mut Vec<AliasBinding>,
594	        diags: &mut Vec<ApplicationDiagnostic>,
595	    ) {
596	        if visiting.iter().any(|m| m == logical_id) {
597	            let cycle: Vec<&str> = visiting
598	                .iter()
599	                .map(String::as_str)
600	                .chain(std::iter::once(logical_id))
601	                .collect();
602	            diags.push(ApplicationDiagnostic::closure_error(
603	                APP014_IMPORT_CYCLE,
604	                format!("import cycle: {}", cycle.join(" -> ")),
605	            ));
606	            return;
607	        }
