632	                            APP014_UNRESOLVED_SPECIFIER,
633	                            format!(
634	                                "import '{spec}' in '{logical_id}' resolves to '{p}', which is not in sources_json"
635	                            ),
636	                        ));
637	                        None
638	                    }
639	                    Err(reason) => {
640	                        diags.push(ApplicationDiagnostic::closure_error(
641	                            APP014_UNRESOLVED_SPECIFIER,
642	                            format!("import '{spec}' in '{logical_id}' is invalid: {reason}"),
643	                        ));
644	                        None
645	                    }
646	                }
