672	                    .collect();
673	                match matches.as_slice() {
674	                    [one] => Some((*one).clone()),
675	                    [] => {
676	                        diags.push(ApplicationDiagnostic::closure_error(
677	                            APP014_UNRESOLVED_SPECIFIER,
678	                            format!(
679	                                "namespace import '{spec}' in '{logical_id}' matches no source-map module"
680	                            ),
681	                        ));
682	                        None
683	                    }
684	                    _ => {
685	                        diags.push(ApplicationDiagnostic::closure_error(
686	                            APP014_UNRESOLVED_SPECIFIER,
687	                            format!(
688	                                "namespace import '{spec}' in '{logical_id}' matches more than one source-map module"
689	                            ),
690	                        ));
691	                        None
692	                    }
693	                }
