774	        .map(|id| {
775	            let (source, ast) = parsed
776	                .get(id)
777	                .or_else(|| std_modules.get(id))
778	                .expect("reachable module was parsed");
779	            ResolvedModule {
780	                logical_id: id.clone(),
781	                source_hash: source_hash(source),
782	                ast: ast.clone(),
