809	            // legal repetitions, not qualified-ID collisions.
810	            let inner = match &decl.node {
811	                crate::parser::ast::AstNode::Export(inner) => &inner.node,
812	                other => other,
813	            };
814	            if matches!(inner, crate::parser::ast::AstNode::Flow { .. }) {
815	                continue;
816	            }
817	            let kind = declaration_kind(&decl.node);
818	            let name = if kind == ResolvedDeclarationKind::ExistingConcept {
819	                name.to_string()
820	            } else {
821	                name.nfc().collect()
822	            };
823	            let qualified_id = format!("{namespace}.{}.{name}", kind_slug(&decl.node));
824	            let symbol = ResolvedSymbol {
825	                qualified_id: qualified_id.clone(),
826	                kind,
827	                exported: exports.contains(name.as_str()),
828	                origin: OriginRef {
829	                    logical_module_id: module.logical_id.clone(),
830	                    line: decl.line,
831	                    column: decl.column,
832	                },
833	                module_index,
834	                declaration_index,
835	            };
