107	/// Load and validate a `SeaSourceSet` through `domainforge-core`.
108	///
109	/// Verifies every source URI/hash, resolves imports from the supplied set,
110	/// enforces finite limits, and rejects unsupported DomainForge versions before
111	/// returning a `DomainModelRef`. No side effects.
112	//
113	// Import resolution uses the pinned library's public parse API
114	// (`parse_source`) to parse every file in-memory, then validates namespace
115	// references and exports adapter-side. This achieves semantic parity with the
116	// library's own ModuleResolver (which is filesystem-based and cannot accept an
117	// in-memory source set) without staging temp files or calling a CLI.
118	pub fn load_validate(source_set: &SeaSourceSet) -> Result<DomainModel, ForgeError> {
119	    // ── Version check ──
120	    if domainforge_core::VERSION != EXPECTED_DOMAINFORGE_VERSION {
121	        return Err(domain_model_error(format!(
122	            "unsupported DomainForge version: expected={EXPECTED_DOMAINFORGE_VERSION} linked={}",
123	            domainforge_core::VERSION
124	        )));
125	    }
126	
127	    // ── Finite limits: source count ──
128	    if source_set.files.len() > MAX_SOURCE_COUNT {
129	        return Err(domain_model_error(format!(
130	            "source count {} exceeds limit {MAX_SOURCE_COUNT}",
131	            source_set.files.len()
132	        )));
133	    }
134	
135	    // ── URI validation + duplicate detection + aggregate bytes ──
136	    let mut seen_uris = HashSet::new();
137	    let mut total_bytes = 0usize;
138	    for file in &source_set.files {
139	        if file.uri.is_empty() {
140	            return Err(domain_model_error("source URI must not be empty".into()));
141	        }
142	        if file.uri.starts_with('/') {
143	            return Err(domain_model_error(format!(
144	                "absolute URI rejected: {}",
145	                file.uri
146	            )));
147	        }
148	        if file.uri.split('/').any(|component| component == "..") {
149	            return Err(domain_model_error(format!(
150	                "traversal URI rejected: {}",
151	                file.uri
152	            )));
153	        }
154	        if !seen_uris.insert(&file.uri) {
155	            return Err(domain_model_error(format!(
156	                "duplicate source URI: {}",
157	                file.uri
158	            )));
159	        }
160	        total_bytes += file.content.len();
161	    }
162	    if total_bytes > MAX_AGGREGATE_BYTES {
163	        return Err(domain_model_error(format!(
164	            "aggregate bytes {total_bytes} exceeds limit {MAX_AGGREGATE_BYTES}"
165	        )));
166	    }
167	
168	    // ── Hash verification for ALL files (not just entry) ──
169	    for file in &source_set.files {
170	        let computed = sha256_content(&file.content);
171	        if computed != file.sha256 {
172	            return Err(domain_model_error(format!(
173	                "source hash drift for {}: declared={} computed={computed}",
174	                file.uri, file.sha256
175	            )));
176	        }
177	    }
178	
179	    // ── Find entry source ──
180	    let entry = source_set
181	        .files
182	        .iter()
183	        .find(|f| f.uri == source_set.entry_uri)
184	        .ok_or_else(|| ForgeError::Input("entry source not found in source set".into()))?;
185	
186	    // ── Parse all files in-memory ──
187	    let mut asts: HashMap<String, domainforge_core::parser::ast::Ast> = HashMap::new();
188	    let mut total_ast_nodes = 0usize;
189	    for file in &source_set.files {
190	        let ast = parse_source(&file.content)
191	            .map_err(|e| domain_model_error(format!("parse failed for {}: {e}", file.uri)))?;
192	        total_ast_nodes += ast.declarations.len();
193	        asts.insert(file.uri.clone(), ast);
194	    }
195	    if total_ast_nodes > MAX_AST_NODES {
196	        return Err(domain_model_error(format!(
197	            "AST node count {total_ast_nodes} exceeds limit {MAX_AST_NODES}"
198	        )));
199	    }
200	
201	    // ── Build namespace → uri map from parsed ASTs ──
202	    let mut ns_to_uri: HashMap<String, String> = HashMap::new();
203	    for file in &source_set.files {
204	        let ast = &asts[&file.uri];
205	        if let Some(ns) = &ast.metadata.namespace {
206	            if ns_to_uri.insert(ns.clone(), file.uri.clone()).is_some() {
207	                return Err(domain_model_error(format!(
208	                    "duplicate namespace '{ns}' declared by multiple files"
209	                )));
210	            }
211	        }
212	    }
213	
214	    // ── Resolve imports from the supplied set ──
215	    resolve_imports(&source_set.files, &asts, &ns_to_uri)?;
216	
217	    // ── Build graph from entry AST (same as pinned library behavior) ──
218	    let options = ParseOptions::default();
219	    let graph = parse_to_graph_with_options(&entry.content, &options)
220	        .map_err(|e| domain_model_error(format!("graph build failed: {e}")))?;
221	
222	    // ── Semantic validation ──
223	    let validation = graph.validate();
224	    if validation.error_count > 0 {
225	        let errors: Vec<String> = validation
226	            .violations
227	            .iter()
228	            .filter(|v| v.severity == Severity::Error)
229	            .map(|v| format!("{}: {}", v.policy_name, v.message))
230	            .collect();
231	        return Err(domain_model_error(format!(
232	            "semantic validation failed: {}",
233	            errors.join("; ")
234	        )));
235	    }
236	
237	    // ── Build source_refs (sorted, all verified files) ──
238	    let mut source_refs: Vec<SourceRef> = source_set
239	        .files
240	        .iter()
241	        .map(|f| SourceRef {
242	            uri: f.uri.clone(),
243	            sha256: f.sha256.clone(),
244	        })
245	        .collect();
246	    source_refs.sort();
247	
248	    // ── Build parse_options_sha256 (includes version + limits) ──
249	    let parse_options_value = serde_json::json!({
250	        "namespace_registry": null,
251	        "entry_path": source_set.entry_uri,
252	        "domainforge_version": domainforge_core::VERSION,
253	        "limits": {
254	            "max_source_count": MAX_SOURCE_COUNT,
255	            "max_aggregate_bytes": MAX_AGGREGATE_BYTES,
256	            "max_import_depth": MAX_IMPORT_DEPTH,
257	            "max_ast_nodes": MAX_AST_NODES,
258	        }
259	    });
260	    let parse_options_sha256 = sha256_json(&parse_options_value)?;
261	
262	    // ── Build semantic_model_sha256 over the canonical 4-tuple ──
263	    let canonical_tuple = serde_json::json!({
264	        "domainforge_version": domainforge_core::VERSION,
265	        "adapter_descriptor_sha256": ADAPTER_DESCRIPTOR_SHA256,
266	        "parse_options_sha256": parse_options_sha256,
267	        "source_refs": source_refs,
268	    });
269	    let semantic_model_sha256 = sha256_json(&canonical_tuple)?;
270	
271	    // ── Extract concept refs from the graph (sorted) ──
272	    let mut concept_refs: Vec<String> = graph
273	        .all_entities()
274	        .iter()
275	        .map(|e| e.name().to_string())
276	        .collect();
277	    concept_refs.extend(graph.all_resources().iter().map(|r| r.name().to_string()));
278	    concept_refs.sort();
279	    concept_refs.dedup();
280	    let mut class_refs: Vec<String> = graph
281	        .all_resources()
282	        .iter()
283	        .map(|resource| resource.name().to_string())
284	        .collect();
285	    class_refs.sort();
286	    class_refs.dedup();
287	
288	    let model_ref = DomainModelRef {
289	        source_refs,
290	        domainforge_version: domainforge_core::VERSION.to_string(),
291	        adapter_descriptor_sha256: ADAPTER_DESCRIPTOR_SHA256.into(),
292	        parse_options_sha256,
293	        semantic_model_sha256,
294	        concept_refs,
295	        class_refs,
296	        validation_evidence_refs: vec![format!(
297	            "validation:error_count={}",
298	            validation.error_count
299	        )],
300	    };
301	
302	    Ok(DomainModel { graph, model_ref })
303	}
