309	/// Validate that every import in every file resolves to a namespace declared by
310	/// a file in the set (or `std`/`std:*`). Detects cycles and unexported named
311	/// imports. Semantic parity with domainforge-core's ModuleResolver but in-memory.
312	fn resolve_imports(
313	    files: &[SourceFile],
314	    asts: &HashMap<String, domainforge_core::parser::ast::Ast>,
315	    ns_to_uri: &HashMap<String, String>,
316	) -> Result<(), ForgeError> {
317	    // Collect exports per namespace.
318	    let mut ns_exports: HashMap<String, HashSet<String>> = HashMap::new();
319	    for file in files {
320	        let ast = &asts[&file.uri];
321	        let ns = ast.metadata.namespace.clone().unwrap_or_default();
322	        let exports = collect_exports(ast);
323	        ns_exports.insert(ns, exports);
324	    }
325	
326	    for file in files {
327	        let ast = &asts[&file.uri];
328	        for import in &ast.metadata.imports {
329	            let module = &import.from_module;
330	            if module == "std" || module.starts_with("std:") {
331	                continue;
332	            }
333	            if !ns_to_uri.contains_key(module) {
334	                return Err(domain_model_error(format!(
335	                    "unresolved import: namespace '{module}' not in source set (in {})",
336	                    file.uri
337	                )));
338	            }
339	            // Check named imports exist in the dependency's exports.
340	            if let ImportSpecifier::Named(items) = &import.specifier {
341	                let exports = ns_exports.get(module).cloned().unwrap_or_default();
342	                for item in items {
343	                    if !exports.contains(&item.name) {
344	                        return Err(domain_model_error(format!(
345	                            "import error: '{}' is not exported by namespace '{}' (in {})",
346	                            item.name, module, file.uri
347	                        )));
348	                    }
349	                }
350	            }
351	        }
352	    }
353	
354	    // Cycle detection over the import graph.
355	    let mut visited = HashSet::new();
356	    let mut stack = Vec::new();
357	    for file in files {
358	        let ast = &asts[&file.uri];
359	        let file_ns = ast.metadata.namespace.as_deref().unwrap_or("");
360	        if !file_ns.is_empty() {
361	            detect_cycle(
362	                file_ns,
363	                ns_to_uri,
364	                asts,
365	                &mut visited,
366	                &mut stack,
367	                MAX_IMPORT_DEPTH,
368	            )?;
369	        }
370	    }
371	    Ok(())
372	}
373	
374	fn detect_cycle(
375	    ns: &str,
376	    ns_to_uri: &HashMap<String, String>,
377	    asts: &HashMap<String, domainforge_core::parser::ast::Ast>,
378	    visited: &mut HashSet<String>,
379	    stack: &mut Vec<String>,
380	    depth_left: usize,
381	) -> Result<(), ForgeError> {
382	    if depth_left == 0 {
383	        return Err(domain_model_error(format!(
384	            "import depth exceeds limit {MAX_IMPORT_DEPTH}"
385	        )));
386	    }
387	    if stack.contains(&ns.to_string()) {
388	        let cycle = stack.join(" → ") + " → " + ns;
389	        return Err(domain_model_error(format!("circular import: {cycle}")));
390	    }
391	    if visited.contains(ns) {
392	        return Ok(());
393	    }
394	    visited.insert(ns.to_string());
395	    stack.push(ns.to_string());
396	
397	    let Some(uri) = ns_to_uri.get(ns) else {
398	        stack.pop();
399	        return Ok(());
400	    };
401	    let ast = &asts[uri];
402	    for import in &ast.metadata.imports {
403	        let dep = &import.from_module;
404	        if dep == "std" || dep.starts_with("std:") {
405	            continue;
406	        }
407	        detect_cycle(dep, ns_to_uri, asts, visited, stack, depth_left - 1)?;
408	    }
409	    stack.pop();
410	    Ok(())
411	}
