413	/// Extract exported declaration names from an AST (mirrors domainforge-core's collect_exports).
414	fn collect_exports(ast: &domainforge_core::parser::ast::Ast) -> HashSet<String> {
415	    let mut exports = HashSet::new();
416	    for node in &ast.declarations {
417	        if let AstNode::Export(inner) = &node.node {
418	            if let Some(name) = declaration_name(&inner.node) {
419	                exports.insert(name.to_string());
420	            }
421	        }
422	    }
423	    exports
424	}
425	
426	fn declaration_name(node: &AstNode) -> Option<&str> {
427	    match node {
428	        AstNode::Entity { name, .. }
429	        | AstNode::Resource { name, .. }
430	        | AstNode::Flow {
431	            resource_name: name,
432	            ..
433	        }
434	        | AstNode::Pattern { name, .. }
435	        | AstNode::Role { name, .. }
436	        | AstNode::Relation { name, .. }
437	        | AstNode::Dimension { name } => Some(name),
438	        _ => None,
439	    }
440	}
