442	/// Normalize a DomainForge authority decision to a SEA Forge candidate disposition.
443	///
444	/// | DomainForge result | SEA Forge candidate disposition |
445	/// |---|---|
446	/// | `Reject` or `Deny` | `deny` |
447	/// | `Escalate` | `escalate` |
448	/// | `Allow` | `allow` |
449	/// | `NotApplicable` | no candidate; `deny` if policy requires DomainForge |
450	pub fn normalize_authority(raw_decision: &str) -> CandidateDisposition {
451	    match raw_decision {
452	        "Allow" => CandidateDisposition::Allow,
453	        "Reject" | "Deny" => CandidateDisposition::Deny,
454	        "Escalate" => CandidateDisposition::Escalate,
455	        _ => CandidateDisposition::Deny, // NotApplicable or unknown → deny-if-required
456	    }
457	}
