459	pub fn evaluate_authority(
460	    model: &DomainModel,
461	    operation_kind: &str,
462	    resource_id: &str,
463	    evidence_refs: Vec<String>,
464	) -> Result<DomainForgeTrace, ForgeError> {
465	    if evidence_refs.is_empty() || model.model_ref.validation_evidence_refs.is_empty() {
466	        return Err(ForgeError::Input(
467	            "DomainForge authority evaluation requires validation evidence".into(),
468	        ));
469	    }
470	    let semantic_target = std::path::Path::new(resource_id)
471	        .file_stem()
472	        .and_then(|stem| stem.to_str())
473	        .is_some_and(|target| {
474	            model
475	                .graph
476	                .all_entities()
477	                .iter()
478	                .any(|entity| entity.name().eq_ignore_ascii_case(target))
479	                || model
480	                    .graph
481	                    .all_resources()
482	                    .iter()
483	                    .any(|resource| resource.name().eq_ignore_ascii_case(target))
484	        });
485	    let raw_decision = match (operation_kind, semantic_target) {
486	        ("write_file", true) => "Allow",
487	        ("write_file", false) => "Reject",
488	        ("execute_command", _) => "NotApplicable",
489	        _ => "NotApplicable",
490	    };
491	    Ok(DomainForgeTrace {
492	        raw_decision: raw_decision.into(),
493	        normalized_disposition: normalize_authority(raw_decision),
494	        reason: "DomainForge evaluated validated model against canonical action".into(),
495	        evidence_refs,
496	    })
497	}
