499	/// In-memory projection of a DomainModel into CALM or RDF.
500	///
501	/// Pure: no filesystem writes, no network calls, no CLI invocations.
502	/// Returns a sorted map of relative_path → content (§7.0a, §10.4a).
503	pub fn project(
504	    model: &DomainModel,
505	    kind: &ProjectionKind,
506	) -> Result<BTreeMap<String, String>, ForgeError> {
507	    match kind {
508	        ProjectionKind::Calm => {
509	            let mut calm_value = domainforge_core::calm::export(&model.graph).map_err(|e| {
510	                ForgeError::Internal(format!("domain_model_error: CALM projection failed: {e}"))
511	            })?;
512	            // Strip non-deterministic timestamp for byte-identical regeneration (§10.7).
513	            // domainforge-core adds sea:timestamp to metadata; remove it so the same
514	            // graph produces identical bytes across calls.
515	            if let Some(metadata) = calm_value
516	                .get_mut("metadata")
517	                .and_then(|m| m.as_object_mut())
518	            {
519	                metadata.remove("sea:timestamp");
520	            }
521	            let mut map = BTreeMap::new();
522	            let encoded = serde_json::to_vec_pretty(&calm_value)
523	                .map_err(|e| ForgeError::Serialization(e.to_string()))?;
524	            map.insert(
525	                "calm.json".into(),
526	                String::from_utf8_lossy(&encoded).into_owned(),
527	            );
528	            Ok(map)
529	        }
530	        ProjectionKind::Rdf => {
531	            let kg =
532	                domainforge_core::kg::KnowledgeGraph::from_graph(&model.graph).map_err(|e| {
533	                    ForgeError::Internal(format!("domain_model_error: KG build failed: {e}"))
534	                })?;
535	            let turtle = kg.to_turtle();
536	            let rdf_xml = kg.to_rdf_xml();
537	            let mut map = BTreeMap::new();
538	            map.insert("model.ttl".into(), turtle);
539	            map.insert("model.rdf".into(), rdf_xml);
540	            Ok(map)
541	        }
542	        ProjectionKind::Kg => {
543	            // M9 (E11): the self-model knowledge-graph projection. The KG is the
544	            // canonical Turtle serialization of the validated graph.
545	            let kg =
546	                domainforge_core::kg::KnowledgeGraph::from_graph(&model.graph).map_err(|e| {
547	                    ForgeError::Internal(format!("domain_model_error: KG build failed: {e}"))
548	                })?;
549	            let turtle = kg.to_turtle();
550	            let mut map = BTreeMap::new();
551	            map.insert("model.ttl".into(), turtle);
552	            Ok(map)
553	        }
554	        _ => Err(ForgeError::Input(format!(
555	            "unsupported projection kind for DomainForge adapter: {kind:?}"
556	        ))),
557	    }
558	}
